const $=id=>document.getElementById(id);
const state={catalog:null,preview:null,provider:'sub2api',library:[],recordId:null};
let revision=0,timer,toastTimer;
const sectionDrafts=new Map();
window.addEventListener('beforeunload',event=>{if(sectionDrafts.size){event.preventDefault();event.returnValue=''}});
const node=(tag,text,className)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(className)e.className=className;return e};
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,2200)}
function error(message=''){$('error').textContent=message;$('error').hidden=!message}
async function api(url,options){const response=await fetch(url,{cache:'no-store',...options});const data=await response.json();if(!response.ok)throw Error(data.error||'后台暂时不可用');return data}
function options(select,items,value){select.replaceChildren(...items.map(item=>{const o=node('option',item.name);o.value=item.id;return o}));if(items.some(x=>x.id===value))select.value=value}
function selectField(id,title,items,value){const label=node('label',title),select=node('select');select.id=id;select.name=id;options(select,items,value);label.append(select);return label}
function updateProduct(){const c=state.catalog,p=c.products.find(x=>x.id===$('product').value);$('variantFields').replaceChildren();if(p.id==='set')for(const [id,title,value]of [['setCraft','被套工艺','plain'],['setSheet','床单款式','standard'],['setPillow','枕套工艺','pillow-plain']])$('variantFields').append(selectField(id,title,c.variants.set.filter(v=>v.group===title),value));else if(c.variants[p.id])$('variantFields').append(selectField('variant',p.id==='quilt'?'被芯类别':p.id==='mat'?'凉席类别':p.id==='mattress'?'床垫款式':p.id==='blanket'?'毯子款式':p.id==='sleepbag'?'更多产品品种':'床单 / 床笠类别',c.variants[p.id],p.id==='quilt'?'winter':p.id==='mat'?'ice':p.id==='mattress'?'thin':p.id==='blanket'?'fleece':p.id==='sleepbag'?'travel':'flat'));options($('fabric'),p.fabrics.map(id=>({id,name:c.materials.find(m=>m.id===id)?.name||id})),p.fabrics[0]);updateMaterial();updateAngles()}
function updateAngles(){const ids=state.catalog.productAngleIds[$('product').value];options($('angle'),ids.map(id=>({id,name:($('product').value==='set'?state.catalog.setAngles?.[id]?.name:null)||state.catalog.angles[id].name})),ids.includes($('angle').value)?$('angle').value:state.catalog.defaultAngle)}
function updateMaterial(){$('fabricField').hidden=$('fabricMode').value!=='selected'||$('product').value==='mat'}
function configuration(){const data=Object.fromEntries(new FormData($('previewForm')));for(const key of ['scale','direction'])data[key]=Number(data[key]);for(const key of ['hasB'])data[key]=$(key).checked;return data}
function copyButton(text,label='复制'){const b=node('button',label,'button');b.type='button';b.onclick=()=>copy(text);return b}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('提示词已复制')}catch{const area=node('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'提示词已复制':'请选中提示词手动复制')}}
function download(name,text,type='text/plain;charset=utf-8'){const link=node('a');const url=URL.createObjectURL(new Blob([text],{type}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function imageCell(element,atlas,cell=atlas.cell){const cols=atlas.cols||4,rows=atlas.rows||3;element.style.backgroundImage='url("'+atlas.src+'")';element.style.backgroundSize=(cols*100)+'% '+(rows*100)+'%';element.style.backgroundPosition=(cols>1?(cell%cols)*100/(cols-1):0)+'% '+(rows>1?Math.floor(cell/cols)*100/(rows-1):0)+'%'}

function sectionContent(item,body,configuration){
  if(item.zh)body.append(node('p',item.zh));
  const pre=node('pre',item.prompt),row=node('div',null,'copy-row');
  const edit=node('button','编辑','button section-editor-control');edit.type='button';
  row.append(copyButton(item.prompt),edit);body.append(pre,row);
  if(item.custom)row.prepend(node('span','已编辑','edited-badge'));
  function open(){
    edit.hidden=true;pre.hidden=true;
    const draft=sectionDrafts.get(item.scope),area=node('textarea');area.value=draft?.text??item.prompt;area.rows=8;area.maxLength=12000;area.setAttribute('aria-label','编辑'+item.name);
    const panel=node('div',null,'section-editor'),hint=node('p','保存后替换此条提示词，两种生图接口共用。范围：'+item.scopeLabel),actions=node('div',null,'editor-actions'),status=node('span',null,'section-save-status');status.setAttribute('role','status');
    const save=node('button','保存并替换','button primary section-editor-control'),cancel=node('button','取消','button'),reset=node('button','恢复默认','button section-editor-control');
    for(const b of [save,cancel,reset])b.type='button';
    actions.append(save,cancel,reset,status);panel.append(hint,area,actions);body.append(panel);
    area.oninput=()=>{if(area.value===item.prompt)sectionDrafts.delete(item.scope);else sectionDrafts.set(item.scope,{text:area.value,version:draft?draft.version:item.version});status.textContent=area.value===item.prompt?'':'有未保存修改'};
    cancel.onclick=()=>{sectionDrafts.delete(item.scope);panel.remove();edit.hidden=false;pre.hidden=false;};
    async function persist(restore=false){
      if(!restore&&!area.value.trim()){status.textContent='提示词不能为空';area.focus();return;}
      for(const b of [save,cancel,reset])b.disabled=true;area.disabled=true;status.textContent='正在保存…';
      try{
        await api('/api/admin/section-edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({configuration,id:item.id,prompt:area.value,reset:restore,version:sectionDrafts.has(item.scope)?sectionDrafts.get(item.scope).version:item.version})});
        sectionDrafts.delete(item.scope);await requestPreview();toast(restore?'已恢复默认提示词':'已保存并替换原提示词');
      }catch(e){status.textContent=e.message;for(const b of [save,cancel,reset])b.disabled=false;area.disabled=false;}
    }
    save.onclick=()=>persist();reset.onclick=()=>persist(true);area.focus();
  }
  edit.onclick=open;if(sectionDrafts.has(item.scope))open();
}
function pendingSections(){document.querySelectorAll('.section-editor-control').forEach(b=>b.disabled=true)}

function setFull(){if(!state.preview)return;$('fullPrompt').textContent=state.preview.prompts[state.provider];document.querySelectorAll('[data-provider]').forEach(b=>b.classList.toggle('active',b.dataset.provider===state.provider));$('attachments').replaceChildren(...(state.provider==='zhipu'?['A/B 面等上传图片先经识图转换为文字摘要，生图阶段接收文字提示词。']:state.preview.attachments.map((label,i)=>(i+1)+'. '+label)).map(label=>node('span',label)))}
function renderPreview(data){state.preview=data;const s=data.settings;const picture=node('div',null,'summary-image');if(data.atlas){imageCell(picture,data.atlas);picture.setAttribute('role','img');picture.setAttribute('aria-label',s.productName+' · '+s.angleName+'角度示例')}else picture.hidden=true;const text=node('div');text.append(node('div',s.productName+' · '+s.variantLabel,'summary-title'),node('p',state.catalog.scenes[s.scene].name+' / '+s.angleName));const tags=node('div',null,'summary-meta');for(const tag of [s.materialName,s.hasB?'A / B 双面':'仅 A 面',s.ratio,s.reference!=='none'?'使用拍摄参考图':null].filter(Boolean))tags.append(node('span',tag,'tag'));text.append(tags);$('previewSummary').replaceChildren(picture,text);
  const previous=$('angle').value;options($('angle'),data.angleOptions,previous);$('angleStrip').replaceChildren();$('angleStrip').classList.toggle('many-angles',data.angleOptions.length>12);if(data.atlas)for(const item of data.angleOptions){const b=node('button',null,'angle-pick'+(item.id===s.angle?' active':''));b.type='button';b.setAttribute('aria-pressed',String(item.id===s.angle));const img=node('span',null,'angle-image'),caption=node('span',item.name,'caption');imageCell(img,data.atlas,item.cell);b.append(img,caption);b.onclick=()=>{$('angle').value=item.id;requestPreview()};$('angleStrip').append(b)}
  $('sections').replaceChildren();for(const item of data.sections){const detail=node('details',null,'prompt-block');detail.open=true;const summary=node('summary',item.name);if(item.overridden)summary.append(node('span','参考图优先','overridden'));const body=node('div',null,'prompt-body');sectionContent(item,body,data.configuration);detail.append(summary,body);$('sections').append(detail)}$('previewNotice').textContent=data.notice;setFull();$('copyFull').disabled=$('exportPreview').disabled=false;
}
async function requestPreview(){pendingSections();clearTimeout(timer);const ticket=++revision;try{const data=await api('/api/admin/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(configuration())});if(ticket!==revision)return;error();state.previewRevision=ticket;renderPreview(data)}catch(e){if(ticket===revision)error(e.message)}}
function schedulePreview(){pendingSections();revision++;clearTimeout(timer);timer=setTimeout(requestPreview,160)}
function libraryEntries(c){const items=[];for(const p of c.products){items.push({category:'product',id:p.id,name:p.name,zh:p.parts,prompt:'此产品的完整结构、A/B 分配、专用角度及款式组合，请在组合提示词中选择查看。',product:p.id});for(const v of c.variants[p.id]||[])items.push({category:'product',id:p.id+'.'+v.id,name:p.name+' · '+v.name,zh:v.hint,group:v.group,prompt:(p.id==='set'?c.setCrafts?.find(o=>o.id===v.id)?.prompt:null)||v.spec||v.hint,product:p.id})}for(const [category,map]of [['scene',c.scenes],['angle',c.angles]])for(const [id,item]of Object.entries(map))items.push({category,id,...item});for(const [id,item]of Object.entries(c.setAngles||{}))items.push({category:'angle',id:'set.'+id,...item,name:'四件套 · '+item.name,product:'set'});for(const m of c.materials)items.push({category:'material',...m});for(const r of c.rules)items.push({category:'rule',...r});return items}
function renderLibrary(){const search=$('search').value.trim().toLowerCase(),category=$('category').value,items=state.library.filter(x=>(category==='all'||x.category===category)&&[x.name,x.zh,x.prompt,x.id,x.group].join(' ').toLowerCase().includes(search));$('libraryCount').textContent=items.length+' 条规则';$('libraryItems').replaceChildren();if(!items.length){$('libraryItems').append(node('div','没有找到匹配的提示词。','empty'));return}for(const item of items){const card=node('article',null,'library-item');card.append(node('h3',item.name),node('small',({product:'产品与子款式',scene:'拍摄场景',angle:'通用拍摄角度',material:'面料质感',rule:'通用规则'})[item.category]+' · '+item.id));if(item.zh)card.append(node('p',item.zh));card.append(node('pre',item.prompt));const row=node('div',null,'copy-row');row.append(copyButton(item.prompt));if(item.product){const b=node('button','查看完整组合');b.onclick=()=>{$('product').value=item.product;updateProduct();const variant=item.id.split('.').slice(1).join('.');if(item.group)$('variantFields').querySelector('[name="'+(item.group==='床单款式'?'setSheet':item.group==='被套工艺'?'setCraft':'setPillow')+'"]').value=variant;else if($('variant')&&variant)$('variant').value=variant;selectTab('preview');requestPreview()};row.append(b)}card.append(row);$('libraryItems').append(card)}}
function recordName(item){const c=state.catalog;return (c.products.find(p=>p.id===item.product)?.name||item.product)+' · '+c.scenes[item.scene]?.name+' · '+(item.angleName||c.angles[item.angle]?.name||item.angle)}
async function refreshRecords(){try{const data=await api('/api/admin/records');$('recordList').replaceChildren();if(!data.records.length){$('recordList').append(node('div','暂无请求记录。前往摄影工作台生成图片后，在此刷新查看。','empty'));return}for(const item of data.records){const b=node('button',null,'record-item'+(state.recordId===item.id?' active':''));b.append(node('strong',recordName(item)),node('small',new Date(item.time).toLocaleString('zh-CN')+' · 第 '+item.index+' 张 · '+item.model));b.onclick=()=>showRecord(item.id);$('recordList').append(b)}error()}catch(e){error(e.message)}}
async function showRecord(id){state.recordId=id;try{const item=await api('/api/admin/records/'+id);if(state.recordId!==id)return;const header=node('div',null,'full-heading'),heading=node('div');heading.append(node('h2',recordName(item)),node('p',new Date(item.time).toLocaleString('zh-CN')+' · '+item.provider+' / '+item.model));header.append(heading,copyButton(item.prompt,'复制真实提示词'));const note=node('p','以下为发送请求前记录的原文。请求记录不代表模型生成成功；请在摄影工作台查看任务结果。','muted');const exportBtn=node('button','导出请求记录','button');exportBtn.onclick=()=>download('织景_实际提示词_'+item.product+'_'+item.angle+'.txt',[recordName(item),item.time,item.model,'产品款式：'+item.size,'',item.prompt].join('\n'));$('recordDetail').replaceChildren(header,note,node('p','款式要求：'+item.size),exportBtn,node('pre',item.prompt));refreshRecords()}catch(e){error(e.message)}}
function selectTab(id){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));for(const name of ['preview','library','records'])$(name+'Panel').hidden=name!==id;if(id==='library')renderLibrary();if(id==='records')refreshRecords()}
$('previewForm').onsubmit=e=>{e.preventDefault();requestPreview()};$('previewForm').onchange=e=>{if(e.target.id==='product')updateProduct();if(e.target.id==='fabricMode')updateMaterial();schedulePreview()};$('notes').oninput=schedulePreview;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>{state.provider=b.dataset.provider;setFull()});$('copyFull').onclick=()=>copy(state.preview.prompts[state.provider]);$('exportPreview').onclick=()=>{const d=state.preview;download('织景_提示词_'+d.settings.product+'_'+d.settings.angle+'.txt',['织景 · 组合提示词预览','版本：'+d.version,JSON.stringify(d.settings,null,2),d.notice,'',...d.sections.map(s=>s.name+'\n'+(s.zh||'')+'\n'+s.prompt),'','Sub2API / 图像编辑\n'+d.prompts.sub2api,'','智谱生图\n'+d.prompts.zhipu].join('\n\n'))};$('search').oninput=renderLibrary;$('category').onchange=renderLibrary;$('exportLibrary').onclick=()=>download('织景_当前提示词库.json',JSON.stringify(state.catalog,null,2),'application/json;charset=utf-8');$('refreshRecords').onclick=refreshRecords;
try{state.catalog=await api('/api/admin/catalog');$('version').textContent='提示词版本 '+state.catalog.version;options($('product'),state.catalog.products,'set');options($('scene'),Object.entries(state.catalog.scenes).map(([id,v])=>({id,name:v.name})),'warm');options($('angle'),Object.entries(state.catalog.angles).map(([id,v])=>({id,name:v.name})),state.catalog.defaultAngle);updateProduct();state.library=libraryEntries(state.catalog);await requestPreview()}catch(e){error(e.message);$('previewSummary').replaceChildren(node('p','提示词未能加载，请刷新或确认本地网站正在运行。'))}
